import sys

def can_rearrange_to_smaller(s, t):
    # Check if there's any character in s that is smaller than the corresponding character in t
    for sc, tc in zip(sorted(s), sorted(t)):
        if sc < tc:
            return True
        elif sc > tc:
            return False
    # If all characters are the same up to the length of the shorter string, check the lengths
    return len(s) < len(t)

